import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { getCandidates, castVote } from "../api";
import CandidateCard from "../components/CandidateCard";

export default function BallotPage({ voterHash }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    getCandidates()
      .then(res => setCandidates(res.data))
      .catch(err => setError("Failed to load candidates"))
      .finally(() => setLoading(false));
  }, []);

  const handleSelect = async (candidateId) => {
    try {
      await castVote(voterHash, candidateId, { choice: candidateId });
      navigate("/success");
    } catch (err) {
      setError(err.response?.data?.error || "Vote failed");
    }
  };

  if (loading) return <p>Loading candidates...</p>;
  if (error) return <p style={{ color: "red" }}>{error}</p>;

  return (
    <div>
      <h2>Select Your Candidate</h2>
      {candidates.map(c => (
        <CandidateCard key={c._id} candidate={c} onSelect={handleSelect} />
      ))}
    </div>
  );
}
